class Solution {
public:
    int maximumDifference(vector<int>& nums) {
        int minSoFar = nums[0];
        int ans = -1;
        for (int j = 1; j < (int)nums.size(); j++) {
            if (nums[j] > minSoFar) {
                int diff = nums[j] - minSoFar;
                if (diff > ans) ans = diff;
            }
            if (nums[j] < minSoFar) {
                minSoFar = nums[j];
            }
        }
        return ans;
    }
};
